/**
 * A function that returns a function such that
 * fn is only called once when the returned function
 * is called.
 *
 * This is used to defer execution of fn to when its
 * result is actually needed.
 *
 * @param fn The function to lazily execute.
 * @returns A function, when called, only invokes fn
 *     at that time and only once.
 *
 * @internal
 */
export declare function lazy<T>(fn: () => T): () => T;
